  add('New crops become available in the Add Farmer form and Crop Management page. Existing survey statistics are not changed until a farmer is added.','కొత్త పంటలు Add Farmer ఫారమ్ మరియు Crop Management పేజీలో అందుబాటులో ఉంటాయి. రైతును జోడించే వరకు ప్రస్తుత సర్వే గణాంకాలు మారవు.','नई फसलें किसान जोड़ें फॉर्म और फसल प्रबंधन पेज पर उपलब्ध होंगी। किसान जोड़ने तक मौजूदा सर्वेक्षण आंकड़े नहीं बदलेंगे।','புதிய பயிர்கள் விவசாயியைச் சேர்க்கும் படிவம் மற்றும் பயிர் மேலாண்மை பக்கத்தில் கிடைக்கும். விவசாயி சேர்க்கப்படும் வரை தற்போதைய கணக்கெடுப்பு புள்ளிவிவரங்கள் மாறாது.');
  add('Add Crop','పంటను జోడించండి','फसल जोड़ें','பயிரைச் சேர்க்கவும்');
  add('Crop Management','పంట నిర్వహణ','फसल प्रबंधन','பயிர் மேலாண்மை');
  add('View crop-wise farmer, area and yield information. Add a new crop to the crop facility for future surveys.','పంటల వారీగా రైతులు, విస్తీర్ణం మరియు దిగుబడి సమాచారాన్ని చూడండి. భవిష్యత్ సర్వేల కోసం పంట సౌకర్యానికి కొత్త పంటను జోడించండి.','फसल के अनुसार किसान, क्षेत्र और उपज की जानकारी देखें। भविष्य के सर्वेक्षणों के लिए फसल सुविधा में नई फसल जोड़ें।','பயிர் வாரியான விவசாயி, பரப்பு மற்றும் விளைச்சல் தகவலைப் பார்க்கவும். எதிர்கால கணக்கெடுப்புகளுக்காக பயிர் வசதியில் புதிய பயிரைச் சேர்க்கவும்.');
  add('Crop Facility','పంట సౌకర్యం','फसल सुविधा','பயிர் வசதி'); add('Category','వర్గం','श्रेणी','வகை'); add('Average Yield/Farmer','సగటు దిగుబడి/రైతు','औसत उपज/किसान','சராசரி விளைச்சல்/விவசாயி'); add('Total Area','మొత్తం విస్తీర్ణం','कुल क्षेत्र','மொத்த பரப்பு'); add('Total Yield','మొత్తం దిగుబడి','कुल उपज','மொத்த விளைச்சல்');
  add('Based on farmer survey records','రైతు సర్వే రికార్డుల ఆధారంగా','किसान सर्वेक्षण रिकॉर्ड के आधार पर','விவசாயி கணக்கெடுப்பு பதிவுகளின் அடிப்படையில்'); add('No farmer survey record yet','ఇంకా రైతు సర్వే రికార్డు లేదు','अभी कोई किसान सर्वेक्षण रिकॉर्ड नहीं है','இன்னும் விவசாயி கணக்கெடுப்பு பதிவு இல்லை'); add('Crop','పంట','फसल','பயிர்');

  // Survey
  add('Analysis of the collected questionnaire fields used in the sample dataset.','నమూనా డేటాసెట్‌లో ఉపయోగించిన సేకరించిన ప్రశ్నాపత్రం అంశాల విశ్లేషణ.','नमूना डेटासेट में उपयोग किए गए एकत्रित प्रश्नावली क्षेत्रों का विश्लेषण।','மாதிரி தரவுத்தொகுப்பில் பயன்படுத்தப்பட்ட சேகரிக்கப்பட்ட கேள்வித்தாள் புலங்களின் பகுப்பாய்வு.');
  add('Modern technology awareness','ఆధునిక సాంకేతిక అవగాహన','आधुनिक तकनीकी जागरूकता','நவீன தொழில்நுட்ப விழிப்புணர்வு'); add('Interested in training','శిక్షణపై ఆసక్తి','प्रशिक्षण में रुचि','பயிற்சியில் ஆர்வம்'); add('Government scheme awareness','ప్రభుత్వ పథకాలపై అవగాహన','सरकारी योजनाओं की जागरूकता','அரசுத் திட்ட விழிப்புணர்வு'); add('Not aware of government schemes','ప్రభుత్వ పథకాలపై అవగాహన లేదు','सरकारी योजनाओं की जानकारी नहीं','அரசுத் திட்டங்கள் குறித்து விழிப்புணர்வு இல்லை'); add('Mobile app users/interested','మొబైల్ యాప్ వినియోగదారులు/ఆసక్తి','मोबाइल ऐप उपयोगकर्ता/रुचि','மொபைல் செயலி பயனர்கள்/ஆர்வம்'); add('Drip irrigation','డ్రిప్ ఇరిగేషన్','ड्रिप सिंचाई','சொட்டு நீர்ப்பாசனம்'); add('Yes responses','అవును సమాధానాలు','हां प्रतिक्रियाएं','ஆம் பதில்கள்'); add('No responses','కాదు సమాధానాలు','नहीं प्रतिक्रियाएं','இல்லை பதில்கள்'); add('Aware responses','అవగాహన ఉన్న సమాధానాలు','जागरूक प्रतिक्रियाएं','விழிப்புணர்வு பதில்கள்'); add('Responses','సమాధానాలు','प्रतिक्रियाएं','பதில்கள்'); add('out of','లో','में से','இல்');
  add('Key Finding: Government Scheme Awareness','ముఖ్య ఫలితం: ప్రభుత్వ పథకాలపై అవగాహన','मुख्य निष्कर्ष: सरकारी योजनाओं की जागरूकता','முக்கிய கண்டுபிடிப்பு: அரசுத் திட்ட விழிப்புணர்வு');
  add('reported that they are not aware of government agricultural schemes.','ప్రభుత్వ వ్యవసాయ పథకాలపై తమకు అవగాహన లేదని తెలిపారు.','ने बताया कि उन्हें सरकारी कृषि योजनाओं की जानकारी नहीं है।','அரசு வேளாண்மைத் திட்டங்கள் குறித்து தங்களுக்கு விழிப்புணர்வு இல்லை என்று தெரிவித்தனர்.');
  add('The project therefore focuses on scheme awareness through the Farmer Support section, awareness activities and official information links.','అందువల్ల ఈ ప్రాజెక్ట్ Farmer Support విభాగం, అవగాహన కార్యక్రమాలు మరియు అధికారిక సమాచార లింకుల ద్వారా పథకాలపై అవగాహన పెంపొందించడంపై దృష్టి పెడుతుంది.','इसलिए यह परियोजना किसान सहायता अनुभाग, जागरूकता गतिविधियों और आधिकारिक सूचना लिंक के माध्यम से योजना जागरूकता पर ध्यान देती है।','எனவே இந்தத் திட்டம் விவசாயி உதவி பகுதி, விழிப்புணர்வு நடவடிக்கைகள் மற்றும் அதிகாரப்பூர்வ தகவல் இணைப்புகள் மூலம் திட்ட விழிப்புணர்வில் கவனம் செலுத்துகிறது.');

  // Support
  add('Government schemes and agricultural support information','ప్రభుత్వ పథకాలు మరియు వ్యవసాయ సహాయ సమాచారం','सरकारी योजनाएं और कृषि सहायता जानकारी','அரசுத் திட்டங்கள் மற்றும் வேளாண்மை ஆதரவு தகவல்கள்');
  add('Government Scheme Awareness Gap','ప్రభుత్వ పథకాలపై అవగాహన లోపం','सरकारी योजनाओं की जागरूकता में कमी','அரசுத் திட்டங்கள் குறித்த விழிப்புணர்வு குறைவு');
  add('The survey shows a significant awareness gap among the sampled farmers.','సర్వేలో పాల్గొన్న రైతుల్లో ప్రభుత్వ పథకాలపై గణనీయమైన అవగాహన లోపం కనిపించింది.','सर्वेक्षण में शामिल किसानों के बीच सरकारी योजनाओं के बारे में जागरूकता की कमी पाई गई।','கணக்கெடுப்பில் பங்கேற்ற விவசாயிகளிடையே அரசுத் திட்டங்கள் குறித்த விழிப்புணர்வு குறைவு காணப்பட்டது.');
  add('surveyed farmers','సర్వే చేసిన రైతులు','सर्वेक्षण किए गए किसान','கணக்கெடுக்கப்பட்ட விவசாயிகள்'); add('reported no awareness','అవగాహన లేదని తెలిపారు','ने जागरूकता नहीं होने की जानकारी दी','விழிப்புணர்வு இல்லை என்று தெரிவித்தனர்');
  add('Government Schemes & Official Information','ప్రభుత్వ పథకాలు మరియు అధికారిక సమాచారం','सरकारी योजनाएं और आधिकारिक जानकारी','அரசுத் திட்டங்கள் மற்றும் அதிகாரப்பூர்வ தகவல்'); add('Farmer Help','రైతులకు సహాయం','किसान सहायता','விவசாயி உதவி');
  add('Farmers can also seek agriculture-related assistance through official government portals and local agriculture department/CSC services. Always verify current eligibility and application requirements on the official portal before applying.','రైతులు అధికారిక ప్రభుత్వ పోర్టల్స్ మరియు స్థానిక వ్యవసాయ శాఖ/CSC సేవల ద్వారా వ్యవసాయ సహాయం పొందవచ్చు. దరఖాస్తు చేసే ముందు ప్రస్తుత అర్హత మరియు అవసరాలను అధికారిక పోర్టల్‌లో ఎల్లప్పుడూ నిర్ధారించుకోండి.','किसान आधिकारिक सरकारी पोर्टल और स्थानीय कृषि विभाग/CSC सेवाओं के माध्यम से कृषि सहायता प्राप्त कर सकते हैं। आवेदन करने से पहले आधिकारिक पोर्टल पर वर्तमान पात्रता और आवश्यकताओं की पुष्टि करें।','விவசாயிகள் அதிகாரப்பூர்வ அரசு இணையதளங்கள் மற்றும் உள்ளூர் வேளாண்மைத் துறை/CSC சேவைகள் மூலம் உதவி பெறலாம். விண்ணப்பிக்கும் முன் தற்போதைய தகுதி மற்றும் தேவைகளை அதிகாரப்பூர்வ இணையதளத்தில் சரிபார்க்கவும்.');
  add('Modern Agricultural Technologies','ఆధునిక వ్యవసాయ సాంకేతికతలు','आधुनिक कृषि तकनीकें','நவீன வேளாண்மை தொழில்நுட்பங்கள்'); add('Official Information','అధికారిక సమాచారం','आधिकारिक जानकारी','அதிகாரப்பூர்வ தகவல்');
  add('How to Use Farmer Support','రైతు సహాయాన్ని ఎలా ఉపయోగించాలి','किसान सहायता का उपयोग कैसे करें','விவசாயி உதவியை எப்படி பயன்படுத்துவது');
  add('Follow these simple steps to find a suitable scheme or agricultural support service.','తగిన పథకం లేదా వ్యవసాయ సహాయ సేవను కనుగొనడానికి ఈ సులభమైన దశలను అనుసరించండి.','उपयुक्त योजना या कृषि सहायता सेवा खोजने के लिए इन सरल चरणों का पालन करें।','பொருத்தமான திட்டம் அல்லது வேளாண்மை உதவி சேவையை கண்டறிய இந்த எளிய படிகளைப் பின்பற்றவும்.');
  add('Identify Your Need','మీ అవసరాన్ని గుర్తించండి','अपनी जरूरत पहचानें','உங்கள் தேவையை கண்டறியவும்'); add('Choose the problem you need help with, such as income support, crop insurance, soil health, credit or irrigation.','ఆదాయ సహాయం, పంట బీమా, మట్టి ఆరోగ్యం, రుణం లేదా నీటిపారుదల వంటి మీకు సహాయం కావాల్సిన సమస్యను ఎంచుకోండి.','आय सहायता, फसल बीमा, मृदा स्वास्थ्य, ऋण या सिंचाई जैसी अपनी जरूरत चुनें।','வருமான ஆதரவு, பயிர் காப்பீடு, மண் ஆரோக்கியம், கடன் அல்லது பாசனம் போன்ற உதவி தேவைப்படும் பிரச்சினையைத் தேர்ந்தெடுக்கவும்.');
  add('Select a Scheme','ఒక పథకాన్ని ఎంచుకోండి','एक योजना चुनें','ஒரு திட்டத்தைத் தேர்ந்தெடுக்கவும்'); add('Review the government schemes below and choose the one that matches your requirement.','క్రింద ఉన్న ప్రభుత్వ పథకాలను పరిశీలించి మీ అవసరానికి సరిపోయే పథకాన్ని ఎంచుకోండి.','नीचे दी गई सरकारी योजनाओं को देखें और अपनी जरूरत के अनुसार योजना चुनें।','கீழே உள்ள அரசுத் திட்டங்களைப் பார்த்து உங்கள் தேவைக்கு ஏற்ற திட்டத்தைத் தேர்ந்தெடுக்கவும்.');
  add('Check Eligibility','అర్హతను తనిఖీ చేయండి','पात्रता जांचें','தகுதியை சரிபார்க்கவும்'); add('Read the eligibility rules and current requirements on the official government portal.','అధికారిక ప్రభుత్వ పోర్టల్‌లో అర్హత నియమాలు మరియు ప్రస్తుత అవసరాలను చదవండి.','आधिकारिक सरकारी पोर्टल पर पात्रता नियम और वर्तमान आवश्यकताओं को पढ़ें।','அதிகாரப்பூர்வ அரசு இணையதளத்தில் தகுதி விதிகள் மற்றும் தற்போதைய தேவைகளைப் படிக்கவும்.');
  add('Keep Documents Ready','పత్రాలను సిద్ధంగా ఉంచండి','दस्तावेज तैयार रखें','ஆவணங்களைத் தயாராக வைத்திருங்கள்'); add('Keep the required identity, land, bank and crop-related documents ready when applicable.','అవసరమైనప్పుడు గుర్తింపు, భూమి, బ్యాంక్ మరియు పంటకు సంబంధించిన పత్రాలను సిద్ధంగా ఉంచండి.','जहां आवश्यक हो, पहचान, भूमि, बैंक और फसल से संबंधित दस्तावेज तैयार रखें।','தேவைப்படும் போது அடையாளம், நிலம், வங்கி மற்றும் பயிர் தொடர்பான ஆவணங்களைத் தயாராக வைத்திருங்கள்.');
  add('Open Official Website','అధికారిక వెబ్‌సైట్ తెరవండి','आधिकारिक वेबसाइट खोलें','அதிகாரப்பூர்வ இணையதளத்தைத் திறக்கவும்'); add('Use the official information button on the selected scheme card and avoid unofficial application links.','ఎంచుకున్న పథక కార్డులోని అధికారిక సమాచార బటన్‌ను ఉపయోగించి, అనధికారిక దరఖాస్తు లింకులను నివారించండి.','चयनित योजना कार्ड के आधिकारिक जानकारी बटन का उपयोग करें और अनौपचारिक आवेदन लिंक से बचें।','தேர்ந்தெடுத்த திட்ட அட்டையில் உள்ள அதிகாரப்பூர்வ தகவல் பொத்தானைப் பயன்படுத்தி அதிகாரப்பூர்வமற்ற விண்ணப்ப இணைப்புகளைத் தவிர்க்கவும்.');
  add('Apply & Check Status','దరఖాస్తు చేసి స్థితిని తనిఖీ చేయండి','आवेदन करें और स्थिति जांचें','விண்ணப்பித்து நிலையைச் சரிபார்க்கவும்'); add('Submit the application through the official channel and keep your application/reference number for status checks.','అధికారిక మార్గం ద్వారా దరఖాస్తును సమర్పించి, స్థితిని తనిఖీ చేయడానికి దరఖాస్తు/రిఫరెన్స్ నంబర్‌ను భద్రంగా ఉంచండి.','आधिकारिक माध्यम से आवेदन जमा करें और स्थिति जांचने के लिए आवेदन/संदर्भ संख्या सुरक्षित रखें।','அதிகாரப்பூர்வ வழியாக விண்ணப்பத்தைச் சமர்ப்பித்து, நிலையைச் சரிபார்க்க விண்ணப்ப/குறிப்பு எண்ணை பாதுகாப்பாக வைத்திருங்கள்.');

  // Reports/settings
  add('Reports & Analytics','నివేదికలు & విశ్లేషణలు','रिपोर्ट और विश्लेषण','அறிக்கைகள் மற்றும் பகுப்பாய்வு'); add('Community findings, evidence and recommended CSP actions.','సమాజ ఫలితాలు, ఆధారాలు మరియు సిఫార్సు చేసిన CSP చర్యలు.','समुदाय के निष्कर्ष, प्रमाण और अनुशंसित CSP कार्रवाइयां।','சமூக கண்டுபிடிப்புகள், ஆதாரங்கள் மற்றும் பரிந்துரைக்கப்பட்ட CSP நடவடிக்கைகள்.'); add('Print Report','నివేదికను ముద్రించండి','रिपोर्ट प्रिंट करें','அறிக்கையை அச்சிடுக');
  add('AgriNexa: Smart Agriculture and Farmer Empowerment: Cultivating Knowledge and AgriNexa: Smart Agriculture and Farmer Empowerment in Agriculture','AgriNexa: Smart Agriculture and Farmer Empowerment: వ్యవసాయంలో జ్ఞానాన్ని పెంపొందిస్తూ కలిసి అభివృద్ధి చెందడం','AgriNexa: Smart Agriculture and Farmer Empowerment: कृषि में ज्ञान बढ़ाते हुए साथ आगे बढ़ना','AgriNexa: Smart Agriculture and Farmer Empowerment: வேளாண்மையில் அறிவை வளர்த்து ஒன்றாக முன்னேறுதல்');
  add('Village:','గ్రామం:','गांव:','கிராமம்:'); add('Department:','శాఖ:','विभाग:','துறை:'); add('Survey:','సర్వే:','सर्वेक्षण:','கணக்கெடுப்பு:'); add('Problems Identified from Survey','సర్వేలో గుర్తించిన సమస్యలు','सर्वेक्षण से पहचानी गई समस्याएं','கணக்கெடுப்பில் கண்டறியப்பட்ட பிரச்சினைகள்'); add('Recommended CSP Actions','సిఫార్సు చేసిన CSP చర్యలు','अनुशंसित CSP कार्रवाइयां','பரிந்துரைக்கப்பட்ட CSP நடவடிக்கைகள்'); add('How the Website Supports the CSP','వెబ్‌సైట్ CSPకి ఎలా మద్దతు ఇస్తుంది','वेबसाइट CSP का समर्थन कैसे करती है','வலைத்தளம் CSP-க்கு எவ்வாறு ஆதரவு அளிக்கிறது'); add('Collect','సేకరించండి','एकत्र करें','சேகரிக்கவும்'); add('Analyze','విశ్లేషించండి','विश्लेषण करें','பகுப்பாய்வு செய்யவும்'); add('Inform','సమాచారం అందించండి','जानकारी दें','தகவல் வழங்கவும்'); add('Act','చర్య తీసుకోండి','कार्रवाई करें','நடவடிக்கை எடுக்கவும்'); add('Farmer survey responses','రైతు సర్వే సమాధానాలు','किसान सर्वेक्षण प्रतिक्रियाएं','விவசாயி கணக்கெடுப்பு பதில்கள்'); add('Problems and percentages','సమస్యలు మరియు శాతాలు','समस्याएं और प्रतिशत','பிரச்சினைகள் மற்றும் சதவீதங்கள்'); add('Official schemes and technologies','అధికారిక పథకాలు మరియు సాంకేతికతలు','आधिकारिक योजनाएं और तकनीकें','அதிகாரப்பூர்வ திட்டங்கள் மற்றும் தொழில்நுட்பங்கள்'); add('Awareness and feedback activities','అవగాహన మరియు అభిప్రాయ కార్యక్రమాలు','जागरूकता और प्रतिक्रिया गतिविधियां','விழிப்புணர்வு மற்றும் கருத்து நடவடிக்கைகள்');
  add('Settings','సెట్టింగ్స్','सेटिंग्स','அமைப்புகள்'); add('This demo uses a local sample dataset. Replace data/farmer_survey_sample.csv and the farmers array in script.js with your actual survey responses when available.','ఈ డెమో స్థానిక నమూనా డేటాసెట్‌ను ఉపయోగిస్తుంది. మీ వాస్తవ సర్వే సమాధానాలు అందుబాటులో ఉన్నప్పుడు data/farmer_survey_sample.csv మరియు script.js లోని farmers array ను మార్చండి.','यह डेमो स्थानीय नमूना डेटासेट का उपयोग करता है। वास्तविक सर्वेक्षण प्रतिक्रियाएं उपलब्ध होने पर data/farmer_survey_sample.csv और script.js में farmers array को बदलें।','இந்த டெமோ உள்ளூர் மாதிரி தரவுத்தொகுப்பைப் பயன்படுத்துகிறது. உங்கள் உண்மையான கணக்கெடுப்பு பதில்கள் கிடைக்கும் போது data/farmer_survey_sample.csv மற்றும் script.js உள்ள farmers array-ஐ மாற்றவும்.'); add('Units: acres and tons. Location: Kakaraparru.','యూనిట్లు: ఎకరాలు మరియు టన్నులు. స్థానం: కాకరపర్రు.','इकाइयां: एकड़ और टन। स्थान: काकरापर्रु।','அலகுகள்: ஏக்கர் மற்றும் டன். இடம்: காகரபர்ரு.');

