  add('PM-KISAN','PM-KISAN','PM-KISAN','PM-KISAN'); add('PMFBY – Crop Insurance','PMFBY – పంట బీమా','PMFBY – फसल बीमा','PMFBY – பயிர் காப்பீடு'); add('Soil Health Card','సాయిల్ హెల్త్ కార్డ్','मृदा स्वास्थ्य कार्ड','மண் ஆரோக்கிய அட்டை'); add('Kisan Credit Card (KCC)','కిసాన్ క్రెడిట్ కార్డ్ (KCC)','किसान क्रेडिट कार्ड (KCC)','கிசான் கிரெடிட் கார்டு (KCC)'); add('e-NAM','e-NAM','e-NAM','e-NAM'); add('PM-KUSUM','PM-KUSUM','PM-KUSUM','PM-KUSUM');
  add('Drip Irrigation','డ్రిప్ ఇరిగేషన్','ड्रिप सिंचाई','சொட்டு நீர்ப்பாசனம்'); add('Crop Rotation','పంటల మార్పిడి','फसल चक्र','பயிர் சுழற்சி'); add('Hydroponics','హైడ్రోపోనిక్స్','हाइड्रोपोनिक्स','ஹைட்ரோபோனிக்ஸ்'); add('Vertical Farming','వర్టికల్ ఫార్మింగ్','वर्टिकल फार्मिंग','செங்குத்து விவசாயம்'); add('Agricultural Drones','వ్యవసాయ డ్రోన్లు','कृषि ड्रोन','வேளாண்மை ட்ரோன்கள்');
  add('Income support scheme for eligible landholding farmer families. Use the official portal to check eligibility, registration and status.','అర్హత ఉన్న భూమి కలిగిన రైతు కుటుంబాలకు ఆదాయ సహాయం అందించే పథకం. అర్హత, నమోదు మరియు స్థితిని తనిఖీ చేయడానికి అధికారిక పోర్టల్‌ను ఉపయోగించండి.','पात्र भूमिधारी किसान परिवारों के लिए आय सहायता योजना। पात्रता, पंजीकरण और स्थिति जांचने के लिए आधिकारिक पोर्टल का उपयोग करें।','தகுதியுள்ள நிலம் கொண்ட விவசாய குடும்பங்களுக்கு வருமான ஆதரவு வழங்கும் திட்டம். தகுதி, பதிவு மற்றும் நிலையை சரிபார்க்க அதிகாரப்பூர்வ இணையதளத்தைப் பயன்படுத்தவும்.');
  add('Crop insurance support for notified crops and risks. Farmers can use the official portal for registration, policy status and claims information.','నోటిఫై చేసిన పంటలు మరియు ప్రమాదాలకు పంట బీమా సహాయం. నమోదు, పాలసీ స్థితి మరియు క్లెయిమ్ సమాచారానికి అధికారిక పోర్టల్‌ను ఉపయోగించవచ్చు.','अधिसूचित फसलों और जोखिमों के लिए फसल बीमा सहायता। पंजीकरण, पॉलिसी स्थिति और दावे की जानकारी के लिए आधिकारिक पोर्टल का उपयोग करें।','அறிவிக்கப்பட்ட பயிர்கள் மற்றும் அபாயங்களுக்கு பயிர் காப்பீட்டு ஆதரவு. பதிவு, பாலிசி நிலை மற்றும் கோரிக்கை தகவல்களுக்கு அதிகாரப்பூர்வ இணையதளத்தைப் பயன்படுத்தலாம்.');
  add('Helps farmers understand soil nutrient status and use soil-test-based fertilizer recommendations.','మట్టి పోషకాల స్థితిని అర్థం చేసుకుని, మట్టి పరీక్ష ఆధారిత ఎరువుల సూచనలను ఉపయోగించడంలో రైతులకు సహాయపడుతుంది.','मिट्टी के पोषक तत्वों की स्थिति समझने और मिट्टी परीक्षण आधारित उर्वरक सुझावों का उपयोग करने में मदद करता है।','மண் ஊட்டச்சத்து நிலையைப் புரிந்து கொண்டு மண் பரிசோதனை அடிப்படையிலான உரப் பரிந்துரைகளைப் பயன்படுத்த உதவுகிறது.');
  add('Agricultural credit facility intended to support eligible farmers with timely farm-related credit.','అర్హత ఉన్న రైతులకు సమయానుకూల వ్యవసాయ రుణ సహాయాన్ని అందించే రుణ సౌకర్యం.','पात्र किसानों को समय पर कृषि संबंधी ऋण सहायता देने के लिए बनाई गई ऋण सुविधा।','தகுதியுள்ள விவசாயிகளுக்கு சரியான நேரத்தில் வேளாண்மை தொடர்பான கடன் உதவி வழங்கும் கடன் வசதி.');
  add('National Agriculture Market platform that supports transparent online agricultural market linkages.','పారదర్శకమైన ఆన్‌లైన్ వ్యవసాయ మార్కెట్ అనుసంధానాలను అందించే జాతీయ వ్యవసాయ మార్కెట్ వేదిక.','पारदर्शी ऑनलाइन कृषि बाजार संपर्कों का समर्थन करने वाला राष्ट्रीय कृषि बाजार मंच।','வெளிப்படையான ஆன்லைன் வேளாண்மை சந்தை இணைப்புகளை ஆதரிக்கும் தேசிய வேளாண்மை சந்தை தளம்.');
  add('Supports solar-energy solutions for the agricultural sector through state-implemented components.','రాష్ట్రాల ద్వారా అమలు చేసే భాగాల ద్వారా వ్యవసాయ రంగానికి సౌర విద్యుత్ పరిష్కారాలను ప్రోత్సహిస్తుంది.','राज्य द्वारा लागू घटकों के माध्यम से कृषि क्षेत्र में सौर ऊर्जा समाधानों का समर्थन करता है।','மாநிலங்களால் செயல்படுத்தப்படும் கூறுகள் மூலம் வேளாண்மைத் துறையில் சூரிய ஆற்றல் தீர்வுகளை ஆதரிக்கிறது.');
  add('Delivers water close to plant roots and can help improve water-use efficiency.','మొక్కల వేర్లకు దగ్గరగా నీటిని అందించి నీటి వినియోగ సామర్థ్యాన్ని మెరుగుపరచడంలో సహాయపడుతుంది.','पौधों की जड़ों के पास पानी पहुंचाकर जल उपयोग दक्षता सुधारने में मदद करती है।','தாவர வேர்களுக்கு அருகில் நீரை வழங்கி நீர் பயன்பாட்டு திறனை மேம்படுத்த உதவுகிறது.'); add('Rotating crops can support soil health and reduce repeated crop-specific pressure.','పంటలను మార్చి సాగు చేయడం మట్టి ఆరోగ్యాన్ని మెరుగుపరచి ఒకే పంటకు సంబంధించిన సమస్యలను తగ్గించవచ్చు.','फसलों को बदल-बदलकर उगाने से मिट्टी का स्वास्थ्य बेहतर हो सकता है और एक ही फसल से जुड़ी समस्याएं कम हो सकती हैं।','பயிர்களை மாற்றி வளர்ப்பது மண் ஆரோக்கியத்தை மேம்படுத்தி ஒரே பயிர் தொடர்பான பிரச்சினைகளை குறைக்கலாம்.'); add('A soil-less growing method that may suit selected crops and controlled environments.','మట్టి లేకుండా నియంత్రిత వాతావరణంలో కొన్ని పంటలను పెంచే విధానం.','मिट्टी के बिना नियंत्रित वातावरण में कुछ फसलों को उगाने की विधि।','மண் இல்லாமல் கட்டுப்படுத்தப்பட்ட சூழலில் சில பயிர்களை வளர்க்கும் முறை.'); add('Uses stacked growing spaces and is mainly useful where land is limited.','పరిమిత భూమి ఉన్న ప్రాంతాల్లో పొరలుగా పంటలను పెంచే విధానం.','सीमित भूमि में फसलों को परतों में उगाने की विधि।','நிலம் குறைவாக உள்ள இடங்களில் அடுக்குகளாக பயிர்களை வளர்க்கும் முறை.'); add('Can support crop observation and selected spraying or monitoring activities where appropriate.','తగిన సందర్భాల్లో పంటల పరిశీలన, పిచికారీ లేదా పర్యవేక్షణకు సహాయపడవచ్చు.','उपयुक्त परिस्थितियों में फसल निरीक्षण, छिड़काव या निगरानी में सहायता कर सकते हैं।','பொருத்தமான சூழலில் பயிர் கண்காணிப்பு, தெளிப்பு அல்லது கண்காணிப்பு நடவடிக்கைகளுக்கு உதவலாம்.');

  // Report list text
  add('Lack of awareness of government schemes — 12 farmers (60%)','ప్రభుత్వ పథకాలపై అవగాహన లోపం — 12 రైతులు (60%)','सरकारी योजनाओं की जानकारी का अभाव — 12 किसान (60%)','அரசுத் திட்டங்கள் குறித்த விழிப்புணர்வு இல்லாமை — 12 விவசாயிகள் (60%)');
  add('Water Scarcity — 5 farmers (25%)','నీటి కొరత — 5 రైతులు (25%)','पानी की कमी — 5 किसान (25%)','நீர் பற்றாக்குறை — 5 விவசாயிகள் (25%)'); add('High Input Cost — 4 farmers (20%)','అధిక ఇన్‌పుట్ ఖర్చు — 4 రైతులు (20%)','अधिक इनपुट लागत — 4 किसान (20%)','அதிக உள்ளீட்டு செலவு — 4 விவசாயிகள் (20%)'); add('Pests and Diseases — 4 farmers (20%)','పురుగులు మరియు వ్యాధులు — 4 రైతులు (20%)','कीट और रोग — 4 किसान (20%)','பூச்சி மற்றும் நோய்கள் — 4 விவசாயிகள் (20%)'); add('Low Market Price — 3 farmers (15%)','తక్కువ మార్కెట్ ధర — 3 రైతులు (15%)','कम बाजार मूल्य — 3 किसान (15%)','குறைந்த சந்தை விலை — 3 விவசாயிகள் (15%)'); add('Lack of Irrigation — 2 farmers (10%)','నీటి పారుదల లోపం — 2 రైతులు (10%)','सिंचाई की कमी — 2 किसान (10%)','பாசன வசதி குறைவு — 2 விவசாயிகள் (10%)'); add('Lack of Technical Knowledge — 2 farmers (10%)','సాంకేతిక జ్ఞానం లోపం — 2 రైతులు (10%)','तकनीकी ज्ञान की कमी — 2 किसान (10%)','தொழில்நுட்ப அறிவு குறைவு — 2 விவசாயிகள் (10%)');
  add('Conduct a government-scheme awareness session using the Farmer Support section.','Farmer Support విభాగాన్ని ఉపయోగించి ప్రభుత్వ పథకాలపై అవగాహన కార్యక్రమాన్ని నిర్వహించండి.','किसान सहायता अनुभाग का उपयोग करके सरकारी योजनाओं पर जागरूकता सत्र आयोजित करें।','விவசாயி உதவி பகுதியைப் பயன்படுத்தி அரசுத் திட்ட விழிப்புணர்வு அமர்வை நடத்துங்கள்.'); add('Explain where farmers can find official scheme information and status/application services.','రైతులు అధికారిక పథక సమాచారం మరియు స్థితి/దరఖాస్తు సేవలను ఎక్కడ పొందవచ్చో వివరించండి.','किसानों को बताएं कि वे आधिकारिक योजना जानकारी और स्थिति/आवेदन सेवाएं कहां पा सकते हैं।','விவசாயிகள் அதிகாரப்பூர்வ திட்ட தகவல் மற்றும் நிலை/விண்ணப்ப சேவைகளை எங்கு பெறலாம் என்பதை விளக்குங்கள்.'); add('Promote water-efficient irrigation and crop-specific water management.','నీటి పొదుపు నీటిపారుదల మరియు పంటకు అనుగుణమైన నీటి నిర్వహణను ప్రోత్సహించండి.','जल-कुशल सिंचाई और फसल-विशिष्ट जल प्रबंधन को बढ़ावा दें।','நீர் திறன் மிக்க பாசனம் மற்றும் பயிர் சார்ந்த நீர் மேலாண்மையை ஊக்குவிக்கவும்.'); add('Share practical guidance on input management, pest monitoring and market awareness.','ఇన్‌పుట్ నిర్వహణ, పురుగు పర్యవేక్షణ మరియు మార్కెట్ అవగాహనపై ఆచరణాత్మక మార్గదర్శకాలను పంచుకోండి.','इनपुट प्रबंधन, कीट निगरानी और बाजार जागरूकता पर व्यावहारिक मार्गदर्शन साझा करें।','உள்ளீட்டு மேலாண்மை, பூச்சி கண்காணிப்பு மற்றும் சந்தை விழிப்புணர்வு குறித்த நடைமுறை வழிகாட்டுதலைப் பகிரவும்.'); add('Collect farmer feedback after awareness activities and compare before/after awareness levels.','అవగాహన కార్యక్రమాల తర్వాత రైతుల అభిప్రాయాలను సేకరించి ముందు/తర్వాత అవగాహన స్థాయిలను పోల్చండి.','जागरूकता गतिविधियों के बाद किसान प्रतिक्रिया एकत्र करें और पहले/बाद के जागरूकता स्तरों की तुलना करें।','விழிப்புணர்வு நடவடிக்கைகளுக்குப் பிறகு விவசாயி கருத்துகளைச் சேகரித்து முன்/பின் விழிப்புணர்வு நிலைகளை ஒப்பிடவும்.');

  add('Main challenge','ప్రధాన సమస్య','मुख्य चुनौती','முக்கிய சவால்');
