  add('Technology awareness','సాంకేతిక అవగాహన','तकनीकी जागरूकता','தொழில்நுட்ப விழிப்புணர்வு'); add('Training interest','శిక్షణపై ఆసక్తి','प्रशिक्षण में रुचि','பயிற்சியில் ஆர்வம்'); add('Government scheme gap','ప్రభుత్వ పథకాలపై అవగాహన లోపం','सरकारी योजनाओं की जागरूकता में कमी','அரசுத் திட்ட விழிப்புணர்வு குறைவு'); add('are not aware','అవగాహన లేదు','जागरूक नहीं हैं','விழிப்புணர்வு இல்லை'); add('report use','వినియోగిస్తున్నట్లు తెలిపారు','उपयोग करने की जानकारी दी','பயன்படுத்துவதாக தெரிவித்தனர்');
